  const ai = ctx.services.ai;
  if (!(await ai.isAvailable("summarize"))) return { text: "", degraded: true };
  const r = await ai.generate({ prompt: String(ctx.args.text), system: "Resume en una frase.", feature: "summarize", maxTokens: 200 });
  return { text: r.text };
};

